mapper.select:
SELECT , COUNT(DISTINCT pod.po_detail_id) AS item_count, COALESCE(CAST(SUM(pod.requested_qty) AS SIGNED), 0) AS total_qty, AS detail_url, AS cancel_url FROM place_order p JOIN branch b ON b.branch_code = p.branch_code LEFT JOIN place_order_detail pod ON pod.po_id = p.po_id WHERE p.branch_code = #{branchCode}
AND DATE(p.request_date) >= #{startDate}
AND DATE(p.request_date) <= #{endDate}
AND () = #{status}
GROUP BY p.po_id, p.po_no, p.branch_code, b.name, p.request_date, p.total_material_cnt, p.total_amount, p.reject_reason, p.status ORDER BY p.request_date DESC, p.po_id DESC

mapper.update:
UPDATE place_order
SET status = #{status},
WHERE po_no = #{poNo}

UPDATE place_order
SET status = #{status},
    reject_reason = #{rejectReason}
WHERE po_no = #{poNo}

UPDATE place_order
SET po_no = #{poNo}
WHERE po_id = #{poId}
